def audited_fractionToDecimal(numerator, denominator):
    if denominator == 0:
        raise ZeroDivisionError("Denominator cannot be zero")

    sign = '-' if (numerator < 0) ^ (denominator < 0) else ''
    numerator, denominator = abs(numerator), abs(denominator)

    integer_part = numerator // denominator
    remainder = numerator % denominator

    if remainder == 0:
        return sign + str(integer_part)

    decimal_part = []
    remainder_map = {}
    i = 0

    while remainder != 0:
        if remainder in remainder_map:
            idx = remainder_map[remainder]
            decimal_part.insert(idx, '(')
            decimal_part.append(')')
            break

        remainder_map[remainder] = i
        remainder *= 10
        digit = remainder // denominator
        decimal_part.append(str(digit))
        remainder = remainder % denominator
        i += 1

    return sign + str(integer_part) + '.' + ''.join(decimal_part)

