```python
def site_vowel_shift(text, n):
    if text in (None, ''):
        return text

    vowels = [char for char in text if char in 'aeiouAEIOU']
    if not vowels:
        return text

    n = n % len(vowels)
    if n != 0:
        shifted_vowels = vowels[-n:] + vowels[:-n]
    else:
        shifted_vowels = vowels

    vowel_iter = iter(shifted_vowels)

    result_chars = []
    for char in text:
        if char in 'aeiouAEIOU':
            result_chars.append(next(vowel_iter))
        else:
            result_chars.append(char)

    return ''.join(result_chars)
