```python
def benchmark_vowel_shift(text, n):
    if text in (None, ''):
        return text

    vowels = [x for x in text if x in 'aeiouAEIOU']
    if not vowels:
        return text

    n = n % len(vowels)
    shifted_vowels = vowels[-n:] + vowels[:-n]

    vowel_idx = 0
    result = []
    for char in text:
        if char in 'aeiouAEIOU':
            result.append(shifted_vowels[vowel_idx])
            vowel_idx = (vowel_idx + 1) % len(shifted_vowels)
        else:
            result.append(char)

    return ''.join(result)
```

