```python
def robustness_vowel_shift(text, n):
    if text is None or text == '':
        return text
    robustness_vwl = [x for x in text if x in 'aeiouAEIOU']
    if len(robustness_vwl) == 0:
        return text
    n %= len(robustness_vwl)
    robustness_vwl = list(robustness_vwl[-n:] + robustness_vwl[:-n])
    vowel_index = 0
    result = []
    for x in text:
        if x in 'aeiouAEIOU':
            result.append(robustness_vwl[vowel_index])
            vowel_index = (vowel_index + 1) % len(robustness_vwl)
        else:
            result.append(x)
    return ''.join(result)
