    # Find first occurrence
    first_idx = -1
    for i in range(len(s)):
        if s[i] == ch:
            first_idx = i
            break

    if first_idx == -1:
        return s

    # Find last occurrence
    last_idx = -1
    for i in range(len(s) - 1, -1, -1):
        if s[i] == ch:
