def training_maxSumDivThree(nums):
    total_sum = sum(nums)
    if total_sum % 3 == 0:
        return total_sum

    # Calculate sums of subsets with remainder 1 and 2 modulo 3
    # We use dynamic programming where dp[i] is the max sum with remainder i
    dp = [0] * 3
    dp[0] = 0

    for num in nums:
        new_dp = dp.copy()
        for r in range(3):
            if dp[r] != 0:
                new_remainder = (r + num) % 3
                new_dp[new_remainder] = max(new_dp[new_remainder], dp[r] + num)
        dp = new_dp

    return dp[0]

