    if len(arr) < k:
        return 0
    target_sum = k * threshold
    window_sum = sum(arr[:k])
    if window_sum >= target_sum:
        return 1 + site_numOfSubarrays(arr[1:], k, threshold) # Recursive approach not optimal, sticking to iterative fix below.

